7	
8	/*
9	 * Copy-first port of node_modules/@salesforce/retail-react-app/app/components/item-variant/item-attributes.jsx
10	 * (retail-react-app 10.0.0), converted to TypeScript per AGENTS.md's copy-first rule (SFCC-270,
11	 * plan step 2.1). Zero functional diff beyond the TypeScript annotations below, the
12	 * `useItemVariant` import path rewrite (see next paragraph), and a temporary `[overrides]`
13	 * console.log marker (verified live, then removed). The `<Stack spacing={1.5} flex={1} {...props}>` defaults-then-spread prop
14	 * order is preserved exactly, unchanged from base.
15	 *
16	 * The base file imports `useItemVariant` from the SFCC package path
17	 * (`@salesforce/retail-react-app/app/components/item-variant`) — inconsistent with its own three
18	 * siblings (item-image/item-name/item-price), which all already import it via the relative `'.'`.
19	 * Since `item-variant/index.tsx` is itself being overridden in this same commit,
20	 * this import is rewritten to match its siblings (`'.'`) per
21	 * .claude/rules/overrideStyling.md's "Importing an already-overridden component from a new
22	 * component" — a base-path import here would silently exercise the base `useItemVariant`/context
23	 * in Storybook and Vitest instead of this override.
24	 *
25	 * `useCurrentBasket` (from the SFCC hooks path) and the `useCurrency`/`app/hooks` barrel are not
26	 * overridden anywhere in this repo (verified by directory listing at time of writing — no
27	 * overrides/app/hooks/use-current-basket.ts, no overrides/app/hooks/index.ts), so both stay on
28	 * the base `@salesforce/retail-react-app/...` path.
29	 *
30	 * SFCC-270 (plan step 2.2): adds `combineAttributeValues`, used by product-item/index.tsx to
31	 * render the Figma cart-item spec's colour+size string ("Lilac Sand, One size") as a single
32	 * combined <Text>, instead of this file's existing per-key behaviour (one <Text> per
33	 * variation-value key, with or without its label per `hideAttributeLabels`) — a genuinely
34	 * different rendering shape, not just `hideAttributeLabels` with the label omitted, since that
35	 * flag still produces one <Text> per key. Defaults to `false`, so the existing per-key
36	 * behaviour (and every other branch in this file — bonus label, quantity, bundles, promotions)
37	 * is unchanged for any caller that doesn't pass it.
38	 */
39	import React from 'react';
40	import { useIntl, FormattedMessage, FormattedNumber } from 'react-intl';
41	import { Flex, Stack, Text, Box, useMultiStyleConfig } from '@salesforce/retail-react-app/app/components/shared/ui';
42	import { useItemVariant } from '.';
43	import PromoPopover from '@salesforce/retail-react-app/app/components/promo-popover';
44	import { useCurrency } from '@salesforce/retail-react-app/app/hooks';
45	import { useCurrentBasket } from '@salesforce/retail-react-app/app/hooks/use-current-basket';
46	import { usePromotions, useProducts, useProduct } from '@salesforce/commerce-sdk-react';
47	import { getDisplayVariationValues } from '@salesforce/retail-react-app/app/utils/product-utils';
48	
49	// See index.tsx's own note on why this is `any` rather than a structural type.
50	type SfccVariant = any;
51	
52	const ZIMM_CART_ITEM_VARIANT_RECIPE = 'ZimmCartItemVariant';
53	
54	type ItemAttributesProps = {
55	  includeQuantity?: boolean;
56	  currency?: string;
57	  excludeBonusLabel?: boolean;
58	  hideAttributeLabels?: boolean;
59	  /** See this file's own SFCC-270 docblock note above. */
60	  combineAttributeValues?: boolean;
61	} & Record<string, any>;
62	
63	/**
64	 * In the context of a cart product item variant, this component renders a styled
65	 * list of the selected variation values as well as any promos (w/ info popover).
66	 */
67	const ItemAttributes = ({
68	  includeQuantity,
69	  currency,
70	  excludeBonusLabel,
71	  hideAttributeLabels = false,
72	  combineAttributeValues = false,
73	  ...props
74	}: ItemAttributesProps) => {
75	  const variant: SfccVariant = useItemVariant();
76	  const styles = useMultiStyleConfig(ZIMM_CART_ITEM_VARIANT_RECIPE, {});
77	  const { data: basket } = useCurrentBasket();
78	  const { currency: activeCurrency } = useCurrency();
79	  const promotionIds = variant.priceAdjustments?.map((adj: SfccVariant) => adj.promotionId) ?? [];
80	  const intl = useIntl();
81	
82	  const displayBonusProductLabel = !excludeBonusLabel && variant?.bonusProductLineItem;
83	
84	  // Fetch all the promotions given by price adjustments. We display this info in
85	  // the promotion info popover when applicable.
86	  const { data: res } = usePromotions(
87	    {
88	      parameters: {
89	        ids: promotionIds.join(','),
90	      },
91	    },
92	    {
93	      enabled: promotionIds.length > 0,
94	    },
95	  );
96	  const promos = res?.data || [];
97	  const variationValues = getDisplayVariationValues(variant?.variationAttributes, variant?.variationValues);
98	
99	  // get variant info for bundled products in cart page and order history page
100	  const productBundleIds = variant?.bundledProductItems?.map(({ productId }: SfccVariant) => productId).join(',') ?? '';
101	  const { data: productBundleVariantData, isLoading: bundleVariantIsLoading } = useProducts(
102	    {
103	      parameters: {
104	        ids: productBundleIds,
105	        allImages: false,
106	      },
107	    },
108	    {
109	      enabled: Boolean(variant?.type?.bundle && productBundleIds),
110	      select: (result: SfccVariant) => {
111	        // formats response so we can easily display child quantity/variant selection
112	        return result?.data?.map((item: SfccVariant) => {
113	          const quantity = variant?.bundledProductItems.find(
114	            (childProduct: SfccVariant) => childProduct.productId === item.id,
115	          )?.quantity;
116	          return {
117	            ...item,
118	            quantity,
119	            variationValues: getDisplayVariationValues(item?.variationAttributes, item?.variationValues),
120	          };
121	        });
122	      },
123	    },
124	  );
125	
126	  // get bundle product data for wishlist page
127	  const { data: productBundleData, isLoading: productBundleIsLoading } = useProduct(
128	    {
129	      parameters: {
130	        id: variant?.id,
131	        allImages: false,
132	      },
133	    },
134	    {
135	      enabled: Boolean(variant?.type?.bundle && !productBundleIds),
136	    },
137	  );
138	
139	  return (
140	    <Stack spacing={1.5} flex={1} {...props}>
141	      {displayBonusProductLabel && (
142	        <Text lineHeight={1} color="black.600" fontSize="sm">
143	          <FormattedMessage defaultMessage="Bonus Product" id="item_attributes.label.bonus_product" />
144	        </Text>
145	      )}
146	
147	      {variationValues && combineAttributeValues && (
148	        <Text sx={styles.colourSize}>{Object.values(variationValues).join(', ')}</Text>
149	      )}
150	
151	      {variationValues &&
152	        !combineAttributeValues &&
153	        Object.keys(variationValues).map((key) => (
154	          <Text lineHeight={1} color="gray.700" fontSize="sm" key={`${key}: ${variationValues[key]}`}>
155	            {hideAttributeLabels ? variationValues[key] : `${key}: ${variationValues[key]}`}
156	          </Text>
157	        ))}
158	
159	      {includeQuantity && (
160	        <Text lineHeight={1} color="gray.700" fontSize="sm">
161	          <FormattedMessage
162	            defaultMessage="Quantity: {quantity}"
163	            values={{ quantity: variant.quantity }}
164	            id="item_attributes.label.quantity"
165	          />
166	        </Text>
167	      )}
168	
169	      {!productBundleIsLoading && productBundleData && !productBundleVariantData && (
170	        <Box>
171	          {/* Deviation from the base file (same labelled-comment convention as
172	                        product-view/index.tsx:659-661/1019-1022): added `?.` before `.map` —
173	                        `bundledProducts` is itself optional on the SDK's real Product type even
174	                        once `productBundleData` is truthy, which strict null checks catches and
175	                        the base file's plain JS did not need to guard against. This is a real,
176	                        narrow behaviour difference from base, not a pure typing satisfier: base
177	                        would throw here if `bundledProducts` were ever undefined on an otherwise
178	                        truthy `productBundleData`; this renders nothing instead. Directionally
179	                        safer (crash -> silent no-render), so left as-is rather than reverted to
180	                        match base's crash-on-that-shape behaviour exactly. */}
181	          {productBundleData?.bundledProducts?.map(({ product, quantity }: SfccVariant) => (
182	            <Box marginTop={2} key={product.id}>
183	              <Text fontSize="sm" color="gray.700" as="b">
184	                {product?.name}
185	              </Text>
186	              <Text fontSize="sm" color="gray.700">
187	                {intl.formatMessage({
188	                  defaultMessage: 'Qty',
189	                  id: 'add_to_cart_modal.label.quantity',
190	                })}
191	                : {quantity}
192	              </Text>
193	            </Box>
194	          ))}
195	        </Box>
196	      )}
197	
198	      {!bundleVariantIsLoading && productBundleVariantData && (
199	        <Box>
200	          <Text fontSize={15} marginTop={3} fontWeight={500}>
201	            {intl.formatMessage({
202	              defaultMessage: 'Selected Options',
203	              id: 'item_attributes.label.selected_options',
204	            })}
205	            :
206	          </Text>
207	          {productBundleVariantData?.map(({ variationValues, name: productName, quantity, id }: SfccVariant) => {
208	            return (
209	              <Box key={id} marginTop={2}>
210	                <Text fontSize="sm" color="gray.700" as="b">
211	                  {productName}
212	                </Text>
213	                <Text fontSize="sm" color="gray.700">
214	                  {intl.formatMessage({
215	                    defaultMessage: 'Qty',
216	                    id: 'add_to_cart_modal.label.quantity',
217	                  })}
218	                  : {quantity}
219	                </Text>
220	                {Object.keys(variationValues).map((key) => {
221	                  const selectedVariant = `${key}: ${variationValues[key]}`;
222	                  return (
223	                    <Text fontSize="sm" color="gray.700" key={selectedVariant}>
224	                      {selectedVariant}
225	                    </Text>
226	                  );
227	                })}
228	              </Box>
229	            );
230	          })}
231	        </Box>
232	      )}
233	
234	      {variant.priceAdjustments?.length > 0 && (
235	        <Flex alignItems="center">
236	          <Text lineHeight={1} color="gray.700" fontSize="sm">
237	            <FormattedMessage defaultMessage="Promotions" id="item_attributes.label.promotions" />
238	            {': '}
239	            <Text as="span" color="green.700">
240	              <FormattedNumber
241	                style="currency"
242	                currency={currency || basket?.currency || activeCurrency}
243	                value={variant.priceAdjustments.reduce((acc: number, adj: SfccVariant) => acc + (adj.price ?? 0), 0)}
244	              />
245	            </Text>
246	          </Text>
247	          <PromoPopover ml={2}>
248	            <Stack>
