import React from 'react';
import { FormattedMessage, useIntl } from 'react-intl';
import { Text, Skeleton } from '@salesforce/retail-react-app/app/components/shared/ui';

// See item-variant/index.tsx's own note on why this is `any` rather than a structural type.
type SfccProduct = any;

type BonusProductQuantityProps = {
  product?: SfccProduct;
};

const BonusProductQuantity = ({ product }: BonusProductQuantityProps) => {
  const intl = useIntl();
  return (
    <Skeleton isLoaded={product}>
      <Text
        fontSize="sm"
        color="gray.700"
        aria-label={intl.formatMessage(
          {
            id: 'item_variant.quantity.label',
            defaultMessage: 'Quantity selector for {productName}. Selected quantity is {quantity}',
          },
          {
            quantity: product?.quantity,
            productName: product?.name,
          },
        )}
      >
        <FormattedMessage
          defaultMessage="Quantity: {quantity}"
          id="bonus_product_item.label.quantity"
          values={{ quantity: product?.quantity }}
        />
      </Text>
    </Skeleton>
  );
};

export default BonusProductQuantity;

